// ── 1. StdoutJsonEmitter ──────────────────────────────────────────────────────

describe("StdoutJsonEmitter", () => {
  it("emits a JSON line with type and at fields", () => {
    const lines: string[] = [];
    vi.spyOn(console, "log").mockImplementation((msg: string) => lines.push(msg));

    const emitter = new StdoutJsonEmitter();
    emitter.emit("test_event", { foo: "bar" });

    expect(lines).toHaveLength(1);
    const parsed = JSON.parse(lines[0]!);
    expect(parsed.type).toBe("test_event");
    expect(parsed.foo).toBe("bar");
    expect(typeof parsed.at).toBe("string");

    vi.restoreAllMocks();
  });

