// ── 7. SubProcessAdapter (Wave 3) ──────────────────────────────────────────
//
// Wave 3 submit() is async / non-blocking — the result arrives via broker
// callback, not via readResult(). Full end-to-end integration tests live in
// tests/subprocess-w3.test.ts. This section covers the surface API contract.

describe("SubProcessAdapter", () => {
  it("constructs with no options", () => {
    const adapter = new SubProcessAdapter();
    expect(adapter).toBeDefined();
    expect(adapter.supervisionSize()).toBe(0);
  });

  it("readResult() returns failed/handle_not_found for any handle (Wave 3 no-op)", async () => {
    const adapter = new SubProcessAdapter();
    const result = await adapter.readResult("unknown-handle-xyz");
    expect(result.terminal_status).toBe("failed");
    expect(result.blocked_reason).toBe("handle_not_found");
  });

  it("readResult() consistently returns handle_not_found for submitted handles too", async () => {
    // Wave 3: result rides in broker callback, not in readResult.
    // Calling readResult for a submitted (or unknown) handle always returns the no-op.
    const adapter = new SubProcessAdapter();
    const result = await adapter.readResult("any-handle");
    expect(result.terminal_status).toBe("failed");
    expect(result.blocked_reason).toBe("handle_not_found");
  });

  it("ack() resolves cleanly when handle is not in supervision map", async () => {
    const adapter = new SubProcessAdapter();
    await expect(adapter.ack("nonexistent-handle")).resolves.not.toThrow();
  });
});

