/**
 * Tests for pr-response/dispatch-reviewer.ts — dispatchReviewer.
 *
 * Unit tests only — no real git operations or Claude spawns. `execSync` and
 * `spawnSync` are mocked via vi.mock. SubProcessAdapter is mocked to avoid
 * subprocess spawning. Filesystem operations use real temp directories.
 *
 * Covers:
 *   1. dispatchReviewer — claim_lost when checkout of task branch fails
 *   2. dispatchReviewer — claim_lost when task status is not in_review
 *   3. dispatchReviewer — claim_lost when last log entry is reviewer_started
 *   4. dispatchReviewer — claim_lost when push of claim commit is rejected with no recovery
 *   5. dispatchReviewer — dispatched on successful claim + async submit
 *   6. dispatchReviewer — reviewer_started log entry written to task YAML on success
 *   7. dispatchReviewer — submitted with handleKind "review" (not "impl")
 *   8. dispatchReviewer — reviewer briefing references prUrl and resultPath
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import type { ExecutorPortInput } from "@workflow/runtime-abi";
import {
  dispatchReviewer,
  type DispatchReviewerOptions,
} from "../src/pr-response/dispatch-reviewer.js";
import { FakeBrokerAdapter } from "@workflow/runtime-abi";

// ── Mock node:child_process ───────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual =
    await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Mock SubProcessAdapter ────────────────────────────────────────────────────

vi.mock("../src/adapters/executor/subprocess.js", () => ({
  SubProcessAdapter: vi.fn().mockImplementation(() => ({
    submit: vi.fn().mockResolvedValue("fake-reviewer-handle"),
  })),
}));

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T3";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "reviewer-agent@test.com";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "review-pr skill",
    repo: "workflow",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: GIT_AUTHOR_EMAIL,
      last_updated_at: "2026-05-08T00:00:00Z",
    },
    pr: {
      url: "https://github.com/tiendv89/agent-workflow/pull/93",
      status: "open",
    },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTask(task: Task, featureId = FEATURE_ID): string {
  const dir = mkdtempSync(join(tmpdir(), "dispatch-reviewer-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${task.id}.yaml`),
    yamlStringify(task),
    "utf-8",
  );
  return dir;
}

function readTaskFromDisk(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
): Task {
  return parseYaml(
    readFileSync(
      join(workspaceRoot, "docs", "features", featureId, "tasks", `${taskId}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try {
      rmSync(d, { recursive: true, force: true });
    } catch {
      /* best-effort */
    }
  }
  vi.clearAllMocks();
});

// ── Mock helpers ──────────────────────────────────────────────────────────────

function mockSpawnSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: "",
    stderr: "",
    status: 0,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockSpawnFailure(stderr = "rejected"): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: "",
    stderr,
    status: 1,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function makeDispatchOpts(
  workspaceRoot: string,
  overrides: Partial<DispatchReviewerOptions> = {},
): DispatchReviewerOptions {
  return {
    workspaceRoot,
    featureId: FEATURE_ID,
    taskId: TASK_ID,
    taskBranch: TASK_BRANCH,
    implRepoRoot: "/fake/impl-repo",
    implRepoUrl: "git@github.com:tiendv89/agent-workflow.git",
    mgmtRepoUrl: "git@github.com:tiendv89/workspace.git",
    gitAuthorEmail: GIT_AUTHOR_EMAIL,
    workflowLocalPath: "/fake/workflow",
    maxTurns: 10,
    maxTokens: 100_000,
    logSinkEnabled: false,
    reviewerModel: "claude-sonnet-4-6",
    workspaceId: "workspace",
    githubToken: "gh_fake_token",
    maxReviewCycles: 3,
    broker: new FakeBrokerAdapter(),
    callbackUrl: "http://127.0.0.1:9999/callback",
    emit: () => {},
    ...overrides,
  };
}

// ── 1. claim_lost when checkout of task branch fails ─────────────────────────

describe("dispatchReviewer — claim_lost on checkout failure", () => {
  it("returns claim_lost and emits reviewer_claim_lost when checkout throws", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementationOnce(() => ""); // fetch
    vi.mocked(execSync).mockImplementationOnce(() => {
      throw new Error("branch not found");
    }); // checkout

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "reviewer_claim_lost")).toBe(true);
  });
});

// ── 2. claim_lost when task status is not in_review ──────────────────────────

describe("dispatchReviewer — claim_lost when task not in_review", () => {
  it("returns claim_lost if task status is 'ready'", async () => {
    const task = makeTask({ status: "ready" });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => ""); // fetch + checkout + reset all pass

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "reviewer_claim_lost")).toBe(true);
    const ev = events.find((e) => e.type === "reviewer_claim_lost")!;
    expect(String(ev.details)).toMatch(/in_review/);
  });

  it("returns claim_lost if task status is 'in_progress'", async () => {
    const task = makeTask({ status: "in_progress" });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => "");

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
  });
});

// ── 3. claim_lost when last log entry is reviewer_started ─────────────────────

describe("dispatchReviewer — claim_lost when already claimed", () => {
  it("returns claim_lost if the last log entry is reviewer_started", async () => {
    const task = makeTask({
      log: [
        {
          action: "reviewer_started",
          by: "other-agent@example.com",
          at: "2026-05-08T10:00:00Z",
          note: "Already claimed by another reviewer.",
        },
      ],
    });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync)
      .mockImplementationOnce(() => "") // fetch
      .mockImplementationOnce(() => "") // checkout
      .mockImplementationOnce(() => ""); // reset --hard

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "reviewer_claim_lost")).toBe(true);
    const ev = events.find((e) => e.type === "reviewer_claim_lost")!;
    expect(String(ev.details)).toMatch(/reviewer_started/);
  });

  it("allows a new claim when reviewer_started is not the last entry", async () => {
    const task = makeTask({
      log: [
        {
          action: "reviewer_started",
          by: "other-agent@example.com",
          at: "2026-05-08T10:00:00Z",
          note: "First reviewer dispatch.",
        },
        {
          action: "blocked",
          by: "other-agent@example.com",
          at: "2026-05-08T11:00:00Z",
          note: "Reviewer blocked mid-review.",
        },
      ],
    });
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess());

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("dispatched");
    expect(events.some((e) => e.type === "reviewer_claim_lost")).toBe(false);
  });
});

// ── 4. claim_lost immediately when push is rejected — no rebase retry ─────────
//
// First-push-wins protocol: a rejected push means another agent claimed first.
// dispatchReviewer must stop without rebasing or retrying — a second push
// attempt could dispatch two reviewers for the same cycle.

describe("dispatchReviewer — claim_lost on push rejection", () => {
  it("returns claim_lost immediately when claim push is rejected", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    // All execSync calls (fetch, checkout, reset, add, commit) succeed.
    vi.mocked(execSync).mockImplementation(() => "");
    // Push is rejected.
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnFailure("non-fast-forward"));

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("claim_lost");
    expect(events.some((e) => e.type === "reviewer_claim_lost")).toBe(true);
  });

  it("makes exactly one push attempt — no rebase retry", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    // 5 execSync calls before the push: fetch, checkout, reset, add, commit.
    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnFailure("rejected"));

    await dispatchReviewer(makeDispatchOpts(wsRoot));

    // Only one spawnSync call (the failed push) — no second push after rebase.
    expect(vi.mocked(spawnSync)).toHaveBeenCalledTimes(1);
    // Only 5 execSync calls — no fetch+rebase after push failure.
    expect(vi.mocked(execSync)).toHaveBeenCalledTimes(5);
  });

  it("never calls git rebase after a rejected push", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnFailure("rejected"));

    await dispatchReviewer(makeDispatchOpts(wsRoot));

    const rebaseCall = vi.mocked(execSync).mock.calls.find(([cmd]) =>
      typeof cmd === "string" && cmd.includes("rebase"),
    );
    expect(rebaseCall).toBeUndefined();
  });
});

// ── 5. dispatched on successful claim + async submit ─────────────────────────

describe("dispatchReviewer — dispatched on success (async submit)", () => {
  it("returns dispatched and emits reviewer_submitted on successful claim and submit", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const events: Record<string, unknown>[] = [];

    vi.mocked(execSync).mockImplementation(() => ""); // all execSync succeed
    vi.mocked(spawnSync).mockReturnValueOnce(mockSpawnSuccess()); // push succeeds

    const outcome = await dispatchReviewer(
      makeDispatchOpts(wsRoot, { emit: (e) => events.push(e) }),
    );

    expect(outcome).toBe("dispatched");
    expect(events.some((e) => e.type === "reviewer_submitted")).toBe(true);
    const submittedEvent = events.find((e) => e.type === "reviewer_submitted")!;
    expect(submittedEvent.task_id).toBe(TASK_ID);
    expect(submittedEvent.feature_id).toBe(FEATURE_ID);
    expect(typeof submittedEvent.handle).toBe("string");
    expect((submittedEvent.handle as string).length).toBeGreaterThan(0);
    expect(submittedEvent.cycle).toBe(1);
  });
});

// ── 6. reviewer_started log entry written to task YAML ───────────────────────

describe("dispatchReviewer — reviewer_started log entry on success", () => {
  it("writes reviewer_started to task YAML on disk", async () => {
